$$\begin{array}{l}
  {{P\left( {0 \leq X \leq \frac{1}{2}‍;1 \leq Y \leq 2} \right)} = {\int_{1}^{2}{\int_{0}^{1 \slash 2}{xydxdy}}}} \\
  {\phantom{P\left( {0 \leq X \leq \frac{1}{2};1 \leq Y \leq 2} \right)} = {\int_{1}^{2}{\left( \left. {\frac{1}{2}‍x^{2}y} \right|_{0}^{1 \slash 2} \right)dy}}} \\
  {\phantom{P\left( {0 \leq X \leq \frac{1}{2};1 \leq Y \leq 2} \right)} = {\int_{1}^{2}{\frac{1}{8}‍ydy = \left. {\frac{1}{16}‍y^{2}} \right|_{1}^{2} = \frac{3}{16}}}}
  \end{array}$$
